      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS where table_schema = 'BGIL_DATA_MODEL'
),
r as (
    select table_name, column_name, data_type, character_maximum_length, numeric_precision, numeric_scale
      from BAGIC_PROD_MIRROR_DB.INFORMATION_SCHEMA.COLUMNS where table_schema = 'MAXI_RAW'
),
x as (
    select 'MAXIMUS' as project, m.*,
           r.data_type as raw_type, r.character_maximum_length as raw_length, r.numeric_precision as raw_precision, r.numeric_scale as raw_scale,
           v.data_type as sat_type, v.character_maximum_length as sat_length, v.numeric_precision as sat_precision, v.numeric_scale as sat_scale,
           case when r.data_type is null then 'RAW_COLUMN_NOT_FOUND'
                when v.data_type is null then 'SAT_COLUMN_NOT_FOUND'
                when v.data_type = 'TEXT' and r.data_type = 'TEXT' and v.character_maximum_length < r.character_maximum_length then 'LENGTH_TRUNCATION_RISK'
                when v.data_type = 'NUMBER' and r.data_type = 'NUMBER'
                     and (v.numeric_scale < r.numeric_scale or v.numeric_precision - v.numeric_scale < r.numeric_precision - r.numeric_scale) then 'NUMERIC_PRECISION_LOSS'
                when v.data_type = r.data_type then 'SAME_TYPE'
                when v.data_type = 'TEXT' then 'STORED_AS_TEXT'
                when m.model_converts then 'CONVERTED_BY_MODEL'
                else 'TYPE_CHANGED' end as classification,
           case when classification in ('SAME_TYPE', 'CONVERTED_BY_MODEL') then 'PASS'
                when classification = 'STORED_AS_TEXT' then 'PASS (value format verified in DM-A1 (b))'
                else 'FAIL' end as status
      from m
      left join r on r.table_name = m.raw_table and r.column_name = m.raw_column
      left join v on v.table_name = m.satellite and v.column_name = m.sat_column
)
select * from x
 order by iff(status = 'FAIL', 0, 1), satellite, sat_column, raw_table;



----------------------------------------------------------------------------------------
-- 2. MAXIMUS — SAT_CHANNEL_DEFINITION   [Implemented]
-- standard satellite, automate_dv.sat; PK DISTRIBUTION_CHANNEL_HKEY; 1 RECORD_SOURCE
-- group(s):
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [2 col(s)]. TRIMMED / BLANK_TO_NULL on trim / nullif columns = documented exception
-- (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct DISTRIBUTION_CHANNEL_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CHANNEL_DEFINITION
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select DISTRIBUTION_CHANNEL_HKEY as hkey, LOAD_DATETIME,
           to_varchar(SUBCHANNELCODE) as SUBCHANNELCODE,
           to_varchar(SUBCHANNELEFFECTIVEDATE) as SUBCHANNELEFFECTIVEDATE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CHANNEL_DEFINITION
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
       and DISTRIBUTION_CHANNEL_HKEY in (select hkey from s1)
    qualify rank() over (partition by DISTRIBUTION_CHANNEL_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_DISTRIBUTION_CHANNEL|' || ((nullif(trim(to_varchar("AGENT_CHANNEL")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar("SUB_CHANNEL") as SUBCHANNELCODE,
               to_varchar("SUB_CHANNEL_EFFECTIVE_DATE") as SUBCHANNELEFFECTIVEDATE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where (hkey, ldts) in (select hkey, LOAD_DATETIME from c1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'SUBCHANNELCODE' as column_name, 'SUB_CHANNEL' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.SUBCHANNELCODE, e.SUBCHANNELCODE) then 0
                when c.SUBCHANNELCODE is null and nullif(trim(e.SUBCHANNELCODE), '') is null then 1
                when c.SUBCHANNELCODE = trim(e.SUBCHANNELCODE) then 2
                when upper(c.SUBCHANNELCODE) = upper(trim(e.SUBCHANNELCODE)) then 3
                when try_to_decimal(c.SUBCHANNELCODE, 38, 10) = try_to_decimal(trim(e.SUBCHANNELCODE), 38, 10) then 4
                when try_to_timestamp_ntz(c.SUBCHANNELCODE) = try_to_timestamp_ntz(trim(e.SUBCHANNELCODE)) then 5
                when length(c.SUBCHANNELCODE) < length(e.SUBCHANNELCODE) and startswith(e.SUBCHANNELCODE, c.SUBCHANNELCODE) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.SUBCHANNELCODE
    union all
    select 'SUBCHANNELEFFECTIVEDATE' as column_name, 'SUB_CHANNEL_EFFECTIVE_DATE' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.SUBCHANNELEFFECTIVEDATE, e.SUBCHANNELEFFECTIVEDATE) then 0
                when c.SUBCHANNELEFFECTIVEDATE is null and nullif(trim(e.SUBCHANNELEFFECTIVEDATE), '') is null then 1
                when c.SUBCHANNELEFFECTIVEDATE = trim(e.SUBCHANNELEFFECTIVEDATE) then 2
                when upper(c.SUBCHANNELEFFECTIVEDATE) = upper(trim(e.SUBCHANNELEFFECTIVEDATE)) then 3
                when try_to_decimal(c.SUBCHANNELEFFECTIVEDATE, 38, 10) = try_to_decimal(trim(e.SUBCHANNELEFFECTIVEDATE), 38, 10) then 4
                when try_to_timestamp_ntz(c.SUBCHANNELEFFECTIVEDATE) = try_to_timestamp_ntz(trim(e.SUBCHANNELEFFECTIVEDATE)) then 5
                when length(c.SUBCHANNELEFFECTIVEDATE) < length(e.SUBCHANNELEFFECTIVEDATE) and startswith(e.SUBCHANNELEFFECTIVEDATE, c.SUBCHANNELEFFECTIVEDATE) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.SUBCHANNELEFFECTIVEDATE
)
select 'MAXIMUS' as project, 'SAT_CHANNEL_DEFINITION' as satellite, 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' as record_source,
       column_name, raw_column, model_rule, count(*) as keys_compared,
       count_if(src_rows > 0 and cls = 0) as exact,
       count_if(src_rows > 0 and cls = 1) as blank_to_null,
       count_if(src_rows > 0 and cls = 2) as trimmed,
       count_if(src_rows > 0 and cls = 3) as case_changed,
       count_if(src_rows > 0 and cls = 4) as number_format_changed,
       count_if(src_rows > 0 and cls = 5) as date_format_changed,
       count_if(src_rows > 0 and cls = 6) as truncated,
       count_if(src_rows > 0 and cls = 7) as value_differs,
       count_if(src_rows = 0) as no_source_row,
       iff(truncated = 0
           and (value_differs = 0 or any_value(r_conv))
           and (trimmed = 0 or any_value(r_trim))
           and (blank_to_null = 0 or any_value(r_nullif))
           and (case_changed = 0 or any_value(r_case))
           and (number_format_changed + date_format_changed = 0 or any_value(r_conv)), 'PASS', 'FAIL') as status
  from r1
 group by column_name, raw_column, model_rule
order by record_source, column_name;



