                when try_to_decimal(c.ADDRESSLINE1, 38, 10) = try_to_decimal(trim(e.ADDRESSLINE1), 38, 10) then 4
                when try_to_timestamp_ntz(c.ADDRESSLINE1) = try_to_timestamp_ntz(trim(e.ADDRESSLINE1)) then 5
