-- documented exception (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_HEALTH_PROFILE
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(DISABILITYBODYLOCATION) as DISABILITYBODYLOCATION
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_HEALTH_PROFILE
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv'
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar("LOCATION_OF_DISABILITY") as DISABILITYBODYLOCATION
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'DISABILITYBODYLOCATION' as column_name, 'LOCATION_OF_DISABILITY' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.DISABILITYBODYLOCATION, e.DISABILITYBODYLOCATION) then 0
                when c.DISABILITYBODYLOCATION is null and nullif(trim(e.DISABILITYBODYLOCATION), '') is null then 1
                when c.DISABILITYBODYLOCATION = trim(e.DISABILITYBODYLOCATION) then 2
                when upper(c.DISABILITYBODYLOCATION) = upper(trim(e.DISABILITYBODYLOCATION)) then 3
                when try_to_decimal(c.DISABILITYBODYLOCATION, 38, 10) = try_to_decimal(trim(e.DISABILITYBODYLOCATION), 38, 10) then 4
                when try_to_timestamp_ntz(c.DISABILITYBODYLOCATION) = try_to_timestamp_ntz(trim(e.DISABILITYBODYLOCATION)) then 5
                when length(c.DISABILITYBODYLOCATION) < length(e.DISABILITYBODYLOCATION) and startswith(e.DISABILITYBODYLOCATION, c.DISABILITYBODYLOCATION) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.DISABILITYBODYLOCATION
)
