-- 84. MAXIMUS — SAT_AUG_PARTY_MARKETING   [Implemented]
-- augmented satellite, automate_dv.sat; PK PARTY_HKEY; 1 RECORD_SOURCE group(s):
-- MAXIMUS_pd_prop_sp_pv [2 col(s)]. TRIMMED / BLANK_TO_NULL on trim / nullif columns =
-- documented exception (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_MARKETING
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(CASHBACKOFFER) as CASHBACKOFFER,
           to_varchar(COUPONTYPE) as COUPONTYPE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_MARKETING
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv'
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
