                when length(c.CASHBACKOFFER) < length(e.CASHBACKOFFER) and startswith(e.CASHBACKOFFER, c.CASHBACKOFFER) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
