       column_name, raw_column, model_rule, count(*) as keys_compared,
       count_if(src_rows > 0 and cls = 0) as exact,
       count_if(src_rows > 0 and cls = 1) as blank_to_null,
       count_if(src_rows > 0 and cls = 2) as trimmed,
       count_if(src_rows > 0 and cls = 3) as case_changed,
       count_if(src_rows > 0 and cls = 4) as number_format_changed,
       count_if(src_rows > 0 and cls = 5) as date_format_changed,
       count_if(src_rows > 0 and cls = 6) as truncated,
       count_if(src_rows > 0 and cls = 7) as value_differs,
       count_if(src_rows = 0) as no_source_row,
       iff(truncated = 0
           and (value_differs = 0 or any_value(r_conv))
           and (trimmed = 0 or any_value(r_trim))
           and (blank_to_null = 0 or any_value(r_nullif))
           and (case_changed = 0 or any_value(r_case))
           and (number_format_changed + date_format_changed = 0 or any_value(r_conv)), 'PASS', 'FAIL') as status
  from r1
 group by column_name, raw_column, model_rule
order by record_source, column_name;



----------------------------------------------------------------------------------------
-- 86. MAXIMUS — SAT_AUG_PARTY_ORGANISATION_PROFILE   [Implemented]
-- augmented satellite, automate_dv.sat; PK PARTY_HKEY; 1 RECORD_SOURCE group(s):
-- MAXIMUS_pd_prop_sp_pv [17 col(s)]. TRIMMED / BLANK_TO_NULL on trim / nullif columns =
-- documented exception (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_ORGANISATION_PROFILE
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(ALTERNATELOCATIONDETAILS) as ALTERNATELOCATIONDETAILS,
           to_varchar(BUSINESSDESCRIPTION) as BUSINESSDESCRIPTION,
           to_varchar(BUSINESSSECTORCODE) as BUSINESSSECTORCODE,
           to_varchar(CLIENTGEOGRAPHY) as CLIENTGEOGRAPHY,
           to_varchar(COORDINATINGOFFICEADDRESS) as COORDINATINGOFFICEADDRESS,
           to_varchar(CREDITLIMITCINNUMBER) as CREDITLIMITCINNUMBER,
           to_varchar(DEDICATEDSTAFFCOUNTFORINSURER) as DEDICATEDSTAFFCOUNTFORINSURER,
           to_varchar(DEDICATEDTEAMLEADERCOUNTFORINSURER) as DEDICATEDTEAMLEADERCOUNTFORINSURER,
           to_varchar(INFRASTRUCTURESUBSECTOR) as INFRASTRUCTURESUBSECTOR,
           to_varchar(OTHERRELATEDENTITIES) as OTHERRELATEDENTITIES,
           to_varchar(OWNERSHIPTYPE) as OWNERSHIPTYPE,
           to_varchar(REGISTEREDBUSINESSTRUSTINDICATOR) as REGISTEREDBUSINESSTRUSTINDICATOR,
           to_varchar(REGISTEREDCOMPANYINDICATOR) as REGISTEREDCOMPANYINDICATOR,
           to_varchar(REPRESENTEDBUSINESSNAME) as REPRESENTEDBUSINESSNAME,
           to_varchar(TOTALTEAMLEADERCOUNT) as TOTALTEAMLEADERCOUNT,
           to_varchar(TOTALTEAMSTRENGTH) as TOTALTEAMSTRENGTH,
           to_varchar(YEAROFESTABLISHMENT) as YEAROFESTABLISHMENT
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_ORGANISATION_PROFILE
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv'
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar("ALTERNATE_LOCATION_DETAILS") as ALTERNATELOCATIONDETAILS,
               to_varchar("BUSINESS_DETAILS") as BUSINESSDESCRIPTION,
               to_varchar("SECTOR_SELECTION") as BUSINESSSECTORCODE,
               to_varchar("CLIENT_GEOGRAPHY") as CLIENTGEOGRAPHY,
               to_varchar("ADDRESS_OF_THE_COORDINATING_OFFICE") as COORDINATINGOFFICEADDRESS,
               to_varchar("CREDIT_LIMIT_CIN_NO") as CREDITLIMITCINNUMBER,
               to_varchar("STAFF_STRENGTH_FOR_BAGIC") as DEDICATEDSTAFFCOUNTFORINSURER,
               to_varchar("TEAM_LEADER_FOR_BAGIC") as DEDICATEDTEAMLEADERCOUNTFORINSURER,
               to_varchar("INFRASTRUCTURE_SUBSECTOR") as INFRASTRUCTURESUBSECTOR,
               to_varchar("OTHER_ENTITIES") as OTHERRELATEDENTITIES,
               to_varchar("OWNERSHIP") as OWNERSHIPTYPE,
               to_varchar("IS_THE_ORGANISATION_A_REGISTERED_BUSINESS_TRUST") as REGISTEREDBUSINESSTRUSTINDICATOR,
               to_varchar("ARE_YOU_REGISTERED_COMPANY") as REGISTEREDCOMPANYINDICATOR,
               to_varchar("BUSINESS_COMPANY") as REPRESENTEDBUSINESSNAME,
               to_varchar("TEAM_LEADER_TOTAL") as TOTALTEAMLEADERCOUNT,
               to_varchar("TOTAL_TEAM_STRENGTH") as TOTALTEAMSTRENGTH,
               to_varchar("YEAR_OF_ESTABLISHMENT_OF_CONTRACTORS_FIRM") as YEAROFESTABLISHMENT
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'ALTERNATELOCATIONDETAILS' as column_name, 'ALTERNATE_LOCATION_DETAILS' as raw_column, 'trim+nullif' as model_rule,
