-- 87. MAXIMUS — SAT_AUG_PARTY_ORG_DIRECTORS   [Implemented]
-- augmented satellite, automate_dv.sat; PK PARTY_HKEY; 1 RECORD_SOURCE group(s):
-- MAXIMUS_pd_prop_sp_pv [1 col(s)]. TRIMMED / BLANK_TO_NULL on trim / nullif columns =
-- documented exception (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_ORG_DIRECTORS
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(DIRECTORANDPARTNERDETAIL) as DIRECTORANDPARTNERDETAIL
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_ORG_DIRECTORS
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv'
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar("DIRECTOR_AND_PARTNER_DETAILS") as DIRECTORANDPARTNERDETAIL
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'DIRECTORANDPARTNERDETAIL' as column_name, 'DIRECTOR_AND_PARTNER_DETAILS' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.DIRECTORANDPARTNERDETAIL, e.DIRECTORANDPARTNERDETAIL) then 0
                when c.DIRECTORANDPARTNERDETAIL is null and nullif(trim(e.DIRECTORANDPARTNERDETAIL), '') is null then 1
                when c.DIRECTORANDPARTNERDETAIL = trim(e.DIRECTORANDPARTNERDETAIL) then 2
                when upper(c.DIRECTORANDPARTNERDETAIL) = upper(trim(e.DIRECTORANDPARTNERDETAIL)) then 3
                when try_to_decimal(c.DIRECTORANDPARTNERDETAIL, 38, 10) = try_to_decimal(trim(e.DIRECTORANDPARTNERDETAIL), 38, 10) then 4
                when try_to_timestamp_ntz(c.DIRECTORANDPARTNERDETAIL) = try_to_timestamp_ntz(trim(e.DIRECTORANDPARTNERDETAIL)) then 5
                when length(c.DIRECTORANDPARTNERDETAIL) < length(e.DIRECTORANDPARTNERDETAIL) and startswith(e.DIRECTORANDPARTNERDETAIL, c.DIRECTORANDPARTNERDETAIL) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.DIRECTORANDPARTNERDETAIL
)
select 'MAXIMUS' as project, 'SAT_AUG_PARTY_ORG_DIRECTORS' as satellite, 'MAXIMUS_pd_prop_sp_pv' as record_source,
