-- augmented satellite, sat_multi_source; PK PARTY_HKEY; 2 RECORD_SOURCE group(s):
-- MAXIMUS_pd_prop_msdp_pv [4 col(s)], MAXIMUS_pd_prop_sp_pv [12 col(s)]. TRIMMED /
-- BLANK_TO_NULL on trim / nullif columns = documented exception (staging trim rule
-- retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_PAYOUT_PROFILE
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_msdp_pv'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(TDSCERTIFICATEISSUEDATE) as TDSCERTIFICATEISSUEDATE,
           to_varchar(TDSCERTIFICATENUMBER) as TDSCERTIFICATENUMBER,
           to_varchar(TDSCERTIFICATETYPE) as TDSCERTIFICATETYPE,
           to_varchar(TDSSECTIONCODE) as TDSSECTIONCODE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_PAYOUT_PROFILE
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_msdp_pv'
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_msdp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) AS VARCHAR))), '')) as hkey,
