               to_varchar("CERTIFICATE_ISSUE_DATE") as TDSCERTIFICATEISSUEDATE,
               to_varchar("TDS_CERTIFICATE_NO") as TDSCERTIFICATENUMBER,
               to_varchar("CERTIFICATE_TYPE") as TDSCERTIFICATETYPE,
               to_varchar("TDS_SECTION_CODE") as TDSSECTIONCODE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'TDSCERTIFICATEISSUEDATE' as column_name, 'CERTIFICATE_ISSUE_DATE' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.TDSCERTIFICATEISSUEDATE, e.TDSCERTIFICATEISSUEDATE) then 0
                when c.TDSCERTIFICATEISSUEDATE is null and nullif(trim(e.TDSCERTIFICATEISSUEDATE), '') is null then 1
                when c.TDSCERTIFICATEISSUEDATE = trim(e.TDSCERTIFICATEISSUEDATE) then 2
                when upper(c.TDSCERTIFICATEISSUEDATE) = upper(trim(e.TDSCERTIFICATEISSUEDATE)) then 3
                when try_to_decimal(c.TDSCERTIFICATEISSUEDATE, 38, 10) = try_to_decimal(trim(e.TDSCERTIFICATEISSUEDATE), 38, 10) then 4
                when try_to_timestamp_ntz(c.TDSCERTIFICATEISSUEDATE) = try_to_timestamp_ntz(trim(e.TDSCERTIFICATEISSUEDATE)) then 5
                when length(c.TDSCERTIFICATEISSUEDATE) < length(e.TDSCERTIFICATEISSUEDATE) and startswith(e.TDSCERTIFICATEISSUEDATE, c.TDSCERTIFICATEISSUEDATE) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.TDSCERTIFICATEISSUEDATE
    union all
    select 'TDSCERTIFICATENUMBER' as column_name, 'TDS_CERTIFICATE_NO' as raw_column, 'trim+nullif' as model_rule,
