                when length(c.TDSCERTIFICATENUMBER) < length(e.TDSCERTIFICATENUMBER) and startswith(e.TDSCERTIFICATENUMBER, c.TDSCERTIFICATENUMBER) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.TDSCERTIFICATENUMBER
    union all
    select 'TDSCERTIFICATETYPE' as column_name, 'CERTIFICATE_TYPE' as raw_column, 'trim+nullif' as model_rule,
