select 'MAXIMUS' as project, 'SAT_AUG_PROVIDER_QUALITY' as satellite, 'MAXIMUS_pd_prop_sp_pv' as record_source,
       column_name, raw_column, model_rule, count(*) as keys_compared,
       count_if(src_rows > 0 and cls = 0) as exact,
       count_if(src_rows > 0 and cls = 1) as blank_to_null,
       count_if(src_rows > 0 and cls = 2) as trimmed,
       count_if(src_rows > 0 and cls = 3) as case_changed,
       count_if(src_rows > 0 and cls = 4) as number_format_changed,
       count_if(src_rows > 0 and cls = 5) as date_format_changed,
       count_if(src_rows > 0 and cls = 6) as truncated,
       count_if(src_rows > 0 and cls = 7) as value_differs,
       count_if(src_rows = 0) as no_source_row,
       iff(truncated = 0
           and (value_differs = 0 or any_value(r_conv))
           and (trimmed = 0 or any_value(r_trim))
           and (blank_to_null = 0 or any_value(r_nullif))
           and (case_changed = 0 or any_value(r_case))
           and (number_format_changed + date_format_changed = 0 or any_value(r_conv)), 'PASS', 'FAIL') as status
  from r1
 group by column_name, raw_column, model_rule
order by record_source, column_name;



----------------------------------------------------------------------------------------
-- 99. MAXIMUS — SAT_AUG_PROVIDER_TARIFF   [Implemented]
-- augmented satellite, automate_dv.sat; PK PARTY_HKEY; 1 RECORD_SOURCE group(s):
-- MAXIMUS_pd_prop_sp_pv [17 col(s)]. TRIMMED / BLANK_TO_NULL on trim / nullif columns =
-- documented exception (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PROVIDER_TARIFF
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(DELAYEDSUBMISSIONDISCOUNTAPPLICABLEINDICATOR) as DELAYEDSUBMISSIONDISCOUNTAPPLICABLEINDICATOR,
           to_varchar(DISCOUNTANDLOADINGTERMS) as DISCOUNTANDLOADINGTERMS,
           to_varchar(DISCOUNTTYPE) as DISCOUNTTYPE,
           to_varchar(FLATRATEBASISINDICATOR) as FLATRATEBASISINDICATOR,
           to_varchar(HOSPITALSPECIFICBILLITEMCODE) as HOSPITALSPECIFICBILLITEMCODE,
           to_varchar(NEGOTIATIONENDDATE) as NEGOTIATIONENDDATE,
           to_varchar(NEGOTIATIONREMARKS) as NEGOTIATIONREMARKS,
           to_varchar(NEGOTIATIONSTARTDATE) as NEGOTIATIONSTARTDATE,
           to_varchar(PACKAGEACCEPTANCEDATE) as PACKAGEACCEPTANCEDATE,
           to_varchar(PACKAGETYPE) as PACKAGETYPE,
           to_varchar(STEPDOWNAPPLICABLEINDICATOR) as STEPDOWNAPPLICABLEINDICATOR,
           to_varchar(SURCHARGEPERCENTAGE) as SURCHARGEPERCENTAGE,
           to_varchar(TARIFFDOCUMENTREFERENCE) as TARIFFDOCUMENTREFERENCE,
           to_varchar(TARIFFDOCUMENTSAVAILABLEINDICATOR) as TARIFFDOCUMENTSAVAILABLEINDICATOR,
           to_varchar(TARIFFLINEREMARKS) as TARIFFLINEREMARKS,
           to_varchar(TARIFFMASTERUPLOADEDINDICATOR) as TARIFFMASTERUPLOADEDINDICATOR,
           to_varchar(TARIFFSTANDARDISEDINDICATOR) as TARIFFSTANDARDISEDINDICATOR
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PROVIDER_TARIFF
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv'
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar("DELAYED_SUBMISSION_DISCOUNT_APPLICABLE") as DELAYEDSUBMISSIONDISCOUNTAPPLICABLEINDICATOR,
