           min(case when equal_null(c.TARIFFSTANDARDISEDINDICATOR, e.TARIFFSTANDARDISEDINDICATOR) then 0
                when c.TARIFFSTANDARDISEDINDICATOR is null and nullif(trim(e.TARIFFSTANDARDISEDINDICATOR), '') is null then 1
                when c.TARIFFSTANDARDISEDINDICATOR = trim(e.TARIFFSTANDARDISEDINDICATOR) then 2
                when upper(c.TARIFFSTANDARDISEDINDICATOR) = upper(trim(e.TARIFFSTANDARDISEDINDICATOR)) then 3
                when try_to_decimal(c.TARIFFSTANDARDISEDINDICATOR, 38, 10) = try_to_decimal(trim(e.TARIFFSTANDARDISEDINDICATOR), 38, 10) then 4
                when try_to_timestamp_ntz(c.TARIFFSTANDARDISEDINDICATOR) = try_to_timestamp_ntz(trim(e.TARIFFSTANDARDISEDINDICATOR)) then 5
                when length(c.TARIFFSTANDARDISEDINDICATOR) < length(e.TARIFFSTANDARDISEDINDICATOR) and startswith(e.TARIFFSTANDARDISEDINDICATOR, c.TARIFFSTANDARDISEDINDICATOR) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.TARIFFSTANDARDISEDINDICATOR
)
select 'MAXIMUS' as project, 'SAT_AUG_PROVIDER_TARIFF' as satellite, 'MAXIMUS_pd_prop_sp_pv' as record_source,
       column_name, raw_column, model_rule, count(*) as keys_compared,
       count_if(src_rows > 0 and cls = 0) as exact,
       count_if(src_rows > 0 and cls = 1) as blank_to_null,
       count_if(src_rows > 0 and cls = 2) as trimmed,
       count_if(src_rows > 0 and cls = 3) as case_changed,
       count_if(src_rows > 0 and cls = 4) as number_format_changed,
       count_if(src_rows > 0 and cls = 5) as date_format_changed,
       count_if(src_rows > 0 and cls = 6) as truncated,
       count_if(src_rows > 0 and cls = 7) as value_differs,
       count_if(src_rows = 0) as no_source_row,
       iff(truncated = 0
           and (value_differs = 0 or any_value(r_conv))
           and (trimmed = 0 or any_value(r_trim))
           and (blank_to_null = 0 or any_value(r_nullif))
           and (case_changed = 0 or any_value(r_case))
           and (number_format_changed + date_format_changed = 0 or any_value(r_conv)), 'PASS', 'FAIL') as status
  from r1
 group by column_name, raw_column, model_rule
order by record_source, column_name;
